package parse_test

import (
	"crypto/sha256"
	"encoding/hex"
	"os"
	"testing"
)

// TestFrozenPayloadBytes decodes the frozen payload byte set of the compact codec transition
// and requires the frozen API JSON byte for byte.
//
// `testdata/payload_frozen_v1.jsonl.gz` was created ONCE when codec byte 1 changed in place
// from the wrapped name-keyed body (`01` + `{data: {...}}`) to the compact id-keyed map.
// It was refreshed for the owner-approved signed int257 key retypes, retaining
// the original frozen row set and API JSON.
// It is NOT regenerated by ordinary baseline regeneration, which writes only
// `payload_contract.jsonl.gz` and `payload_contract.metadata.json`. Change this
// file only with the owner's decision, together with the pinned sha256 below.
//
// Each row carries fixture_id, action_id, type, payload_hex, wire_hex and the frozen `api`
// (the wire column is the envelope carrier, which the payload alone cannot reproduce). The
// payload bytes are decoded by the current decoder, so renumbering or retyping an existing
// registry key - or reformatting these bytes - fails here.
const (
	frozenPayloadPath   = "testdata/payload_frozen_v1.jsonl.gz"
	frozenPayloadSHA256 = "35caf32938175163f97b23b566e6217cb94b7b36ef9739132a424eebc53db868"
	frozenPayloadRows   = 1218
)

func TestFrozenPayloadBytes(t *testing.T) {
	blob, err := os.ReadFile(frozenPayloadPath)
	if err != nil {
		t.Fatal(err)
	}
	digest := sha256.Sum256(blob)
	if got := hex.EncodeToString(digest[:]); got != frozenPayloadSHA256 {
		t.Fatalf("frozen set sha256 = %s, want %s (created once at the codec transition, edit only with the owner's decision)", got, frozenPayloadSHA256)
	}
	checkAPIBaseline(t, frozenPayloadPath, frozenPayloadRows)
}
